\subsection{Detailed derivation for the constraint (\ref{P7_c_2})}
\normalem

{
First,
by using the MM method,
we can obtain a lower bound of 
the term 
$\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}\vert^2$ 
in (\ref{P7_c_2}) as follows}
\begin{align}
&\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}\vert^2 
\geq
2\text{Re}\{ ({\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0})^H {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i} \}
-
\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\vert^2.\label{P7_c_2_1}
\end{align}


In the following, 
we rewrite terms in (\ref{P7_c_2_1}) into a compact form w.r.t. $\Delta\mathbf{h}_{c,k}$.
Specifically, 
by substituting $\mathbf{h}_{c,k} = \hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k}$
into $\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\vert^2$,
we can expand it as follows
\begin{align}
&\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\vert^2 
=\mathbf{w}_{c,i,0}^H{\mathbf{h}}_{c,k} {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\label{P7_c_2_1_1}
&= \mathbf{w}_{c,i,0}^H(\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})
(\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})^H\mathbf{w}_{c,i,0}\nonumber
&=\mathbf{w}_{c,i,0}^H\hat{\mathbf{h}}_{c,k} \hat{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}
+\mathbf{w}_{c,i,0}^H\hat{\mathbf{h}}_{c,k} \Delta{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\nonumber
&+\mathbf{w}_{c,i,0}^H\Delta{\mathbf{h}}_{c,k} \hat{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}
+\mathbf{w}_{c,i,0}^H\Delta{\mathbf{h}}_{c,k} \Delta{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\nonumber
&=\Delta\mathbf{h}_{c,k}^H\mathbf{B}_{1,i}\Delta\mathbf{h}_{c,k} + 
2\text{Re}\{ \mathbf{b}_{1,k,i}^H \Delta\mathbf{h}_{c,k}\} + c_{1,k,i},\nonumber
\end{align}
where
\begin{align}
c_{1,k,i} \triangleq \hat{\mathbf{h}}_{c,k}^H \mathbf{w}_{c,i,0}\mathbf{w}_{c,i,0}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{b}_{1,k,i} \triangleq \mathbf{w}_{c,i,0}\mathbf{w}_{c,i,0}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{B}_{1,i} \triangleq \mathbf{w}_{c,i,0}\mathbf{w}_{c,i,0}^H.
\end{align}


Furthermore,
$2\text{Re}\{ ({\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0})^H {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i} \}$
can be compactly rewritten as
\begin{align}
&2\text{Re}\{ ({\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0})^H {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i} \}\label{P7_c_2_1_2}
&=2\text{Re}\{ ((\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})^H\mathbf{w}_{c,i,0})^H (\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})^H\mathbf{w}_{c,i} \}\nonumber
&= 2\text{Re}\{
\mathbf{w}_{c,i,0}^H\hat{\mathbf{h}}_{c,k} \hat{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}
+\mathbf{w}_{c,i,0}^H\hat{\mathbf{h}}_{c,k} \Delta{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}\nonumber
&+\mathbf{w}_{c,i,0}^H\Delta{\mathbf{h}}_{c,k} \hat{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}
+\mathbf{w}_{c,i,0}^H\Delta{\mathbf{h}}_{c,k} \Delta{\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}
\}
\nonumber
&=\Delta\mathbf{h}_{c,k}^H(\mathbf{B}_{2,i} +\mathbf{B}_{2,i}^H )\Delta\mathbf{h}_{c,k}
+ 
2\text{Re}\{ (\mathbf{b}_{2,k,i}+\mathbf{b}_{3,k,i})^H \Delta\mathbf{h}_{c,k}\} + c_{2,k,i},
\nonumber
\end{align}
where
\begin{align}
&\mathbf{b}_{3,k,i} \triangleq \mathbf{w}_{c,i,0}\mathbf{w}_{c,i}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{B}_{2,i} \triangleq \mathbf{w}_{c,i}\mathbf{w}_{c,i,0}^H,
c_{2,k,i} \triangleq 2\text{Re}\{ \hat{\mathbf{h}}_{c,k}^H \mathbf{w}_{c,i}\mathbf{w}_{c,i,0}^H  \hat{\mathbf{h}}_{c,k} \},
&\mathbf{b}_{2,k,i} \triangleq \mathbf{w}_{c,i}\mathbf{w}_{c,i,0}^H  \hat{\mathbf{h}}_{c,k}.\nonumber
\end{align}


Based on (\ref{P7_c_2_1_1}) and (\ref{P7_c_2_1_2}),
the right-hand side of (\ref{P7_c_2_1}) can be rewritten as
\begin{align}
&2\text{Re}\{ ({\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0})^H {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i} \}
-
\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i,0}\vert^2
&\Leftrightarrow
\Delta\mathbf{h}_{c,k}^H\mathbf{B}_{3,i} \Delta\mathbf{h}_{c,k} + 
2\text{Re}\{ \mathbf{b}_{4,k,i}^H \Delta\mathbf{h}_{c,k}\} + c_{3,k,i},\nonumber
\end{align}
where
\begin{align}
&c_{3,k,i} \triangleq c_{2,k,i} - c_{1,k,i},
\mathbf{b}_{4,k,i} \triangleq \mathbf{b}_{3,k,i} + \mathbf{b}_{2,k,i} - \mathbf{b}_{1,k,i},
\mathbf{B}_{3,i} \triangleq \mathbf{B}_{2,i} + \mathbf{B}_{2,i}^H - \mathbf{B}_{1,i}.
\end{align}





Using the MM method,
the term 
$\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{r,n}\vert^2$
in 
(\ref{P7_c_2})
can be lower-bounded as follows
\begin{align}
&\vert {\mathbf{h}}_{c,k}^H  \mathbf{w}_{r,n}\vert^2
\geq
2\text{Re}\{ ({\mathbf{h}}_{c,k}^H\mathbf{w}_{r,n,0})^H{\mathbf{h}}_{c,k}^H\mathbf{w}_{r,n}\}
-
\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{r,n,0}\vert^2
&=\Delta\mathbf{h}_{c,k}^H\mathbf{B}_{7,n}\Delta\mathbf{h}_{c,k} + 
2\text{Re}\{ \mathbf{b}_{9,k,n}^H \Delta\mathbf{h}_{c,k}\} + c_{7,k,n},\nonumber
\end{align}
where the newly introduced coefficients are defined in (\ref{Coef_P7_c1_SCA_1}).
\begin{figure*}
\begin{small}
\begin{align}
&c_{5,k,n}\!\! \triangleq\!\! \hat{\mathbf{h}}_{c,k}^H \mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{b}_{6,k,n}\!\! \triangleq\!\! \mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{B}_{5,n}\! \triangleq\! \mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H,
c_{6,k,n}\! \triangleq\! 2\text{Re}\{ \hat{\mathbf{h}}_{c,k}^H \mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H\hat{\mathbf{h}}_{c,k} \},\nonumber
&\mathbf{b}_{7,k,n} \triangleq \mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{b}_{8,k,n} \triangleq \mathbf{w}_{r,n,0}\mathbf{w}_{r,n}^H  \hat{\mathbf{h}}_{c,k},
\mathbf{B}_{6,n} \triangleq \mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H,
c_{7,k,n} \triangleq c_{6,k,n} - c_{5,k,n},\nonumber
&\mathbf{b}_{9,k,n} \triangleq \mathbf{b}_{7,k,n} + \mathbf{b}_{8,k,n} - \mathbf{b}_{6,k,n},
\mathbf{B}_{7,n} \triangleq \mathbf{B}_{6,n} + \mathbf{B}_{6,n}^H - \mathbf{B}_{5,n}.\label{Coef_P7_c1_SCA_1}
\end{align}
\end{small}
\boldsymbol{\hrule}
\end{figure*}

Thus,
based on the above transformations,
the constraint (\ref{P7_c_2}) can be rewritten as
\begin{align}
\Delta\mathbf{h}_{c,k}^H\mathbf{B}_{9}\Delta\mathbf{h}_{c,k}
\! +\! 
2\text{Re}\{ \mathbf{b}_{11,k}^H \Delta\mathbf{h}_{c,k}\}\! +\! c_{9,k}+\sigma_{c,k}^2
\!\geq\! \mu_k, \label{P7_c_2_T1}
\end{align}
where
\begin{align}
&\mathbf{B}_{9} \triangleq {\sum}_{i=1}^{K}\mathbf{B}_{3,i} + {\sum}_{n=1}^{N}\mathbf{B}_{7,n},
\mathbf{b}_{11,k} \triangleq {\sum}_{i=1}^{K}\mathbf{b}_{4,k,i} + {\sum}_{n=1}^{N}\mathbf{b}_{9,k,n},
&c_{9,k} \triangleq {\sum}_{i=1}^{K}c_{3,k,i} + {\sum}_{n=1}^{N}c_{7,k,n}.  \nonumber
\end{align}

{
It is worth noting that (\ref{P7_c_2_T1}) is not an exact reformulation of (\ref{P7_c_2}), 
but provides a conservative sufficient condition for it. 
According to the property of the MM method, 
if 
(\ref{P7_c_2_T1}) is satisfied for all 
$\Vert\Delta\mathbf{h}_{c,k}\Vert_2 \leq \xi_{c,k}$, 
the original constraint (\ref{P7_c_2}) is also guaranteed to hold.}










Note that (\ref{P7_c_2_T1}) is still a semi-infinite inequality constraint due to the CSI uncertainty.
By leveraging the S-Procedure,
(\ref{P7_c_2_T1}) 
can be equivalently transformed into the following LMIs as
\begin{align}
&\Delta\mathbf{h}_{c,k}^H\mathbf{B}_{9}\Delta\mathbf{h}_{c,k}
\! +\! 
2\text{Re}\{ \mathbf{b}_{11,k}^H \Delta\mathbf{h}_{c,k}\}\! +\! c_{9,k}+\sigma_{c,k}^2
\!\geq\! \mu_k 
&\Rightarrow
\left[
\begin{array}{cc}
\varpi_{1,k} \mathbf{I} + \mathbf{B}_{9} & \mathbf{b}_{11,k} 
\mathbf{b}_{11,k}^H  & c_{9,k}+\sigma_{c,k}^2 - \mu_k - \varpi_{1,k}\xi_{c,k}^2
\end{array}
\right] \succeq \mathbf{0},\nonumber
\end{align}
where
$ \boldsymbol{\varpi}_1=[\varpi_{1,1},\cdots,\varpi_{1,K}]^T \geq 0 $.









\subsection{Detailed derivation for the constraint (\ref{P7_c_3})}
\normalem


To circumvent the CSI uncertainty in constraint (\ref{P7_c_3}),
by adopting Schur's complement Lemma \cite{ref_Convex Optimization},
the inequality constraint (\ref{P7_c_3}) can be recast into matrix form as follows
\begin{align}
&{\sum}_{i\neq k}^{K}\vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{c,i}\vert^2
+{\sum}_{n=1}^{N} \vert {\mathbf{h}}_{c,k}^H\mathbf{w}_{r,n}\vert^2
+\sigma_{c,k}^2\leq \nu_k \label{P7_c_3_T1}
&\Rightarrow
\left[
\begin{array}{cc}
\nu_k - \sigma_{c,k}^2 & \mathbf{h}_{c,k}^H \mathbf{W}_{cr,-k}
\mathbf{W}_{cr,-k}^H\mathbf{h}_{c,k}  &  \mathbf{I}
\end{array}
\right] \succeq \mathbf{0},\nonumber
\end{align}
where
\begin{align}
\mathbf{W}_{cr,-k} \triangleq 
&[ \mathbf{w}_{c,1},\cdots ,\mathbf{w}_{c,k-1},\mathbf{w}_{c,k+1},  \cdots, \mathbf{w}_{c,K},
& \mathbf{w}_{r,1}, \cdots, \mathbf{w}_{r,N} ] \in \mathbb{C}^{N\times(K-1+N)} .\nonumber
\end{align}



By substituting $\mathbf{h}_{c,k} = \hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k}$ into (\ref{P7_c_3_T1}),
we can obtain
\begin{align}
&\left[
\begin{array}{cc}
\nu_k - \sigma_{c,k}^2 & (\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})^H \mathbf{W}_{cr,-k}
\mathbf{W}_{cr,-k}^H(\hat{\mathbf{h}}_{c,k} + \Delta\mathbf{h}_{c,k})  &  \mathbf{I}
\end{array}
\right]\succeq \mathbf{0}\label{P7_c_3_T2}
&\Leftrightarrow
\left[
\begin{array}{cc}
\nu_k - \sigma_{c,k}^2 & \hat{\mathbf{h}}_{c,k}^H \mathbf{W}_{cr,-k}
\mathbf{W}_{cr,-k}^H\hat{\mathbf{h}}_{c,k}  &  \mathbf{I}
\end{array}
\right]
-
\left[\!\!\!
\begin{array}{cc}
1
\mathbf{0}
\end{array}\!\!\!
\right]
\Delta \mathbf{h}_{c,k}^H
\left[\!\!\!
\begin{array}{cc}
\mathbf{0},
\mathbf{W}_{cr,-k}
\end{array}\!\!\!
\right]
-
\left[\!\!\!
\begin{array}{cc}
\mathbf{0}
\mathbf{W}_{cr,-k}
\end{array}\!\!\!
\right]
\Delta\mathbf{h}_{c,k}
\left[\!\!\!
\begin{array}{cc}
1,
\mathbf{0}
\end{array}\!\!\!
\right]
\succeq \mathbf{0}
\nonumber

&
\Leftrightarrow
\left[
\begin{array}{cc}
\nu_k - \sigma_{c,k}^2 & \hat{\mathbf{h}}_{c,k}^H \mathbf{W}_{cr,-k}
\mathbf{W}_{cr,-k}^H\hat{\mathbf{h}}_{c,k}  &  \mathbf{I}
\end{array}
\right]
\succeq 
\left[\!\!\!
\begin{array}{cc}
1
\mathbf{0}
\end{array}\!\!\!
\right]
\Delta \mathbf{h}_{c,k}^H
\left[\!\!\!
\begin{array}{cc}
\mathbf{0},
-\mathbf{W}_{cr,-k}
\end{array}\!\!\!
\right]
+
\left[\!\!\!
\begin{array}{cc}
\mathbf{0}
-\mathbf{W}_{cr,-k}
\end{array}\!\!\!
\right]
\Delta\mathbf{h}_{c,k}
\left[\!\!\!
\begin{array}{cc}
1,
\mathbf{0}
\end{array}\!\!\!
\right]
.\nonumber
\end{align}







By using the above sign-definiteness lemma,
the equivalent LMIs of (\ref{P7_c_3_T2}) can be written as
\begin{align}
&
\left[
\begin{array}{ccc}
\nu_k - \sigma_{c,k}^2-\varpi_{2,k} & \hat{\mathbf{h}}_{c,k}^H \mathbf{W}_{cr,-k} & \mathbf{0}
\mathbf{W}_{cr,-k}^H\hat{\mathbf{h}}_{c,k}  &  \mathbf{I}  & \xi_{c,k}\mathbf{W}_{cr,-k}^H
\mathbf{0}  &  \xi_{c,k}\mathbf{W}_{cr,-k}  & \varpi_{2,k}\mathbf{I}
\end{array}
\right] 
\succeq 
\mathbf{0},
\end{align}
where
$ \boldsymbol{\varpi}_2=[\varpi_{2,1},\cdots,\varpi_{2,K}]^T \geq 0 $.













\subsection{Detailed derivation for the constraint (\ref{P7_c_6})}
\normalem


First,
we convexify the terms 
$\vert{\mathbf{h}}_{r}^H \mathbf{w}_{r,i}\vert^2 $
and 
$\vert{\mathbf{h}}_{r}^H \mathbf{w}_{c,k}\vert^2$ 
in (\ref{P7_c_6})
via invoking the MM method as follows
\begin{align}
&\vert{\mathbf{h}}_{r}^H \mathbf{w}_{r,i}\vert^2
\geq
2\text{Re}\{(\mathbf{h}_{r}^H \mathbf{w}_{r,i,0})^H\mathbf{h}_{r}^H \mathbf{w}_{r,i}\}
-\vert\mathbf{h}_{r}^H \mathbf{w}_{r,i,0}\vert^2

&=\Delta\mathbf{h}_{r}^H\mathbf{B}_{12,i}\Delta\mathbf{h}_{r} + 
2\text{Re}\{ \mathbf{b}_{15,i}^H \Delta\mathbf{h}_{r}\} + c_{12,i},\nonumber

&\vert{\mathbf{h}}_{r}^H \mathbf{w}_{c,k}\vert^2
\geq
2\text{Re}\{(\mathbf{h}_{r}^H \mathbf{w}_{c,k,0})^H\mathbf{h}_{r}^H \mathbf{w}_{c,k}\}
-\vert\mathbf{h}_{r}^H \mathbf{w}_{c,k,0}\vert^2

&=\Delta\mathbf{h}_{r}^H\mathbf{B}_{16,k}\Delta\mathbf{h}_{r} + 
2\text{Re}\{ \mathbf{b}_{20,k}^H \Delta\mathbf{h}_{r}\} + c_{16,k},\nonumber
\end{align}
respectively,
where the newly introduced notations above are defined in (\ref{Coef_P7_c2_SCA_1}).
\begin{figure*}
\begin{small}
\begin{align}
&c_{10,n}\!\triangleq\! 
\hat{\mathbf{h}}_{r}^H \mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{b}_{12,n}\triangleq 
\mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{B}_{10,n}\triangleq 
\mathbf{w}_{r,n,0}\mathbf{w}_{r,n,0}^H,
c_{11,n} \triangleq 2\text{Re}\{ \hat{\mathbf{h}}_{r}^H \mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H\hat{\mathbf{h}}_{r} \},
\label{Coef_P7_c2_SCA_1}
&
\mathbf{b}_{13,n}\!\triangleq \!
\mathbf{w}_{r,n,0}\mathbf{w}_{r,n}^H  \hat{\mathbf{h}}_{r},
\mathbf{b}_{14,n}\triangleq 
\mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{B}_{11,n}\!\triangleq \!
\mathbf{w}_{r,n}\mathbf{w}_{r,n,0}^H,
c_{12,n}\triangleq  c_{11,n}\! -\! c_{10,n},
\mathbf{b}_{15,n}\triangleq  \mathbf{b}_{14,n} + \mathbf{b}_{13,n} - \mathbf{b}_{12,n},\nonumber
&\mathbf{B}_{12,n}\triangleq 
\mathbf{B}_{11,n} + \mathbf{B}_{11,n}^H - \mathbf{B}_{10,n},
c_{14,k}\triangleq 
\hat{\mathbf{h}}_{r}^H \mathbf{w}_{c,k,0}\mathbf{w}_{c,k,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{b}_{17,k}\triangleq 
\mathbf{w}_{c,k,0}\mathbf{w}_{c,k,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{B}_{14,k}\triangleq 
\mathbf{w}_{c,k,0}\mathbf{w}_{c,k,0}^H,
\nonumber
&c_{15,k} \triangleq 2\text{Re}\{ \hat{\mathbf{h}}_{r}^H \mathbf{w}_{c,k}\mathbf{w}_{c,k,0}^H\hat{\mathbf{h}}_{r} \},
\mathbf{b}_{18,k}\triangleq 
\mathbf{w}_{c,k,0}\mathbf{w}_{c,k}^H  \hat{\mathbf{h}}_{r},
\mathbf{b}_{19,k}\triangleq 
\mathbf{w}_{c,k}\mathbf{w}_{c,k,0}^H  \hat{\mathbf{h}}_{r},
\mathbf{B}_{15,k}\triangleq 
\mathbf{w}_{c,k}\mathbf{w}_{c,k,0}^H,\nonumber
&c_{16,k}\triangleq  c_{15,k} - c_{14,k},
\mathbf{b}_{20,k}\triangleq  \mathbf{b}_{18,k} + \mathbf{b}_{19,k} - \mathbf{b}_{17,k},
\mathbf{B}_{16,k}\triangleq 
\mathbf{B}_{15,k} + \mathbf{B}_{15,k}^H - \mathbf{B}_{14,k}.\nonumber
\end{align}
\end{small}
\boldsymbol{\hrule}
\end{figure*}

Therefore,
the constraint (\ref{P7_c_6}) can be reformulated as follows
\begin{align}
\Delta\mathbf{h}_{r}^H\mathbf{B}_{18}\Delta\mathbf{h}_{r} + 
2\text{Re}\{ \mathbf{b}_{22}^H \Delta\mathbf{h}_{r}\} + c_{18}
\geq P_r, \label{P7_c_6_T_1}
\end{align}
where
\begin{align}
&\mathbf{B}_{18} \triangleq {\sum}_{k=1}^{K}\mathbf{B}_{16,k} + {\sum}_{n=1}^{N}\mathbf{B}_{12,n},
\mathbf{b}_{22} \triangleq {\sum}_{k=1}^{K}\mathbf{b}_{20,k} + {\sum}_{n=1}^{N}\mathbf{b}_{15,n},
&c_{18} \triangleq {\sum}_{k=1}^{K}c_{16,k} + {\sum}_{n=1}^{N}c_{12,n}. \nonumber
\end{align}


By applying the S-Procedure again,
the following LMI of (\ref{P7_c_6_T_1}) can be given as
\begin{align}
&\Delta\mathbf{h}_{r}^H\mathbf{B}_{18}\Delta\mathbf{h}_{r} + 
2\text{Re}\{ \mathbf{b}_{22}^H \Delta\mathbf{h}_{r}\} + c_{18}
\geq P_r
&\Rightarrow
\left[
\begin{array}{cc}
\varpi_{3} \mathbf{I} + \mathbf{B}_{18} & \mathbf{b}_{22} 
\mathbf{b}_{22}^H  & c_{18}-P_r - \varpi_{3}\xi_{r}^2
\end{array}
\right] \succeq \mathbf{0},\nonumber
\end{align}
where
$ \varpi_3 \geq 0 $ is a slack variable.










