	Compute $\widehat{\bf H}_{\rm eff} = {\bf{W}}_{\rm{BB}}^{\rm (2)H} {\bf{W}}_{\rm{RF}}^{\rm H} \widehat{\bf H}{\bf{F}}_{\rm{RF}}{\bf{F}}_{\rm{BB}}^{(2)}$
	Compute SVD of ${\bf R}_{\rm n}^{-\frac{1}{2}}\widehat{\bf H}_{\rm eff}$ and return $\bf V$ and $\boldsymbol \Sigma$
	\If {$\max\limits_k \frac{1}{\sigma^2_k}\varepsilon_{\rm eff}^2\beta_k^2 - \rho_k >0$ }{
	$\tilde{ k} = \argmax\limits_k \frac{1}{\sigma^2_k}\varepsilon_{\rm eff}^2\beta_k^2  - \rho_k$
	Discard  $\tilde{ k}^{\rm th}$ data stream from the set of data streams
	$ N_{\rm s} = N_{\rm s} -1$ 
	\If {$N_{\rm s} > \frac{N^{\rm RF}_{\rm t}}{2}$}{
		return to \textbf{2}
		}
	}
	Obtain $k_{\rm max} = \argmax\limits_{k} \frac{1}{\sigma_k^2}\left( \frac{1}{\rho_k}-1 \right)$
	Compute $a_{k_{\rm max}}, b_{k_{\rm max}}, c_{k_{\rm max}}, \text{ and } p_{\rm max}$ in \eqref{power_root}
		\For{$k=1$ \rm{to} $N_{\rm s} \wedge k \neq k_{\rm max}$}
		{
		Compute $a_k, b_k, c_k, \text{ and } p_k$ in \eqref{power_root}
		}
	Compute ${\bf F}_{\rm BB}^{(1)} = \bf V P^{\frac{1}{2}}$
	Compute ${\bf W}_{\rm BB}^{(1)}$ from \eqref{bb_combining}
	\KwOutput{$ {\bf F}_{\rm BB}^{(1)}, {\bf{F}}_{\rm{BB}}^{(2)}, {\bf{F}}_{\rm{RF}}, {\bf W}_{\rm BB}^{(1)},{\bf{W}}_{\rm{BB}}^{(2)}, \text{ and }{\bf{W}}_{\rm{RF}} $}
	\caption{Low-Complexity Scheme for Solving \eqref{qos_problem}}
\end{small}
\end{algorithm}
\vspace{-5 pt}
\section{Multi-User Hybrid Beamforming}\label{mu_section}

In this section, we extend our iterative and low-complexity { HB schemes} to multi-user systems.
\vspace{-10 pt}
\subsection{System Model}

The multi-user system includes one transmitter equipped with $N_{\rm t}$ antennas and $N_{\rm t}^{\rm RF}$ RF chains, and $U$ receivers each with $N_{\rm r}$ antennas and $N_{\rm r}^{\rm RF}$ RF chains. The vector ${{\bf s}=[{\bf s}_1^{\rm T}, {\bf s}_2^{\rm T},\ldots, {\bf s}_U^{\rm T}]^{\rm T}}$ is transmitted, where ${\bf s}_u\in \mathbb{C}^{N_{\rm{s}} \times 1}$. The estimated vector of {the} received symbols at any given instance by receiver $u$ is
\begin{equation}\label{s_mu}
\hat{\bf{s}}_u = {\bf{W}}_{{\rm BB},u}^{\rm H}{\bf{W}}_{{\rm RF},u}^{\rm H}{\bf H}_u{ \bf{F}}_{\rm{RF}}{\bf F}_{\rm BB}{\bf{s}} + {\bf{W}}_{{\rm BB},u}^{\rm H}{\bf{W}}_{{\rm RF},u}^{\rm H}{\bf n}_u,
\end{equation}
where ${\bf{W}}_{{\rm BB},u}$ and ${\bf{W}}_{{\rm RF},u}$ are the baseband combiner and phase {shifter} matrices of receiver $u$, respectively; ${\bf H}_u$ is the channel gain matrix between the transmitter and receiver $u$, and ${\bf n}_u$ is the noise vector at receiver $u$. CSI is assumed to be erroneous, i.e., ${\bf H}_u = \widehat{\bf H}_u + \boldsymbol \Delta_u$, and ${\rm Pr}\{\|\boldsymbol\Delta_u \|_{\rm F}\le \varepsilon_u\} =  P_{\rm in}$.

The baseband precoder and combiner matrices are divided into two stages each, {such that} ${\bf F}_{\rm BB} = {\bf F}_{\rm BB}^{(2)}{\bf F}_{\rm BB}^{(1)}$ and ${\bf W}_{{\rm BB},u} = {\bf W}_{{\rm BB},u}^{(2)}{\bf W}_{{\rm BB},u}^{(1)}$, where ${\bf{F}}_{\rm{BB}}^{(1)}=\left[{\bf{F}}_{\rm{BB},1}^{(1)},\ldots, {\bf{F}}_{\rm{BB},U}^{(1)}\right]$, and ${\bf{F}}_{{\rm BB},u}^{(1)}\in \mathbb{C}^{UN_{\rm{s}} \times N_{\rm{s}}}$ is the baseband precoder for receiver $u$. We wish to minimize the transmit power while satisfying MSE constraints {(i.e., $[{\bf E}_u]_{k,k}\le \rho_{u,k}$)}, where ${\bf E}_u$ is {the} MSE matrix estimated by receiver $u$.
\vspace{-3 mm}
\subsection{RF Beamforming}

{The} RF combiner of receiver $u$ is obtained by approximating the left eigenvectors of $\widehat{\bf H}_u$ derived by SVD $\widehat{\bf H}_u = \widehat{\bf U}_u \widehat{\boldsymbol \Sigma}_u \widehat{\bf V}_u^{\rm H}$. In other words, we use RF beamforming in Section \ref{analog_section} with proper substitutions to find ${\bf W}_{{\rm RF},u}$ and ${\bf W}_{{\rm BB},u}^{\rm (2)}$ by minimizing $\|{\bf W}_{{\rm RF},u} {\bf W}_{{\rm BB},u}^{\rm (2)} - \widehat{\bf U}_u \|^2_{\rm F}$. {The} RF precoder is then obtained by minimizing $\|{\bf F}_{{\rm RF}} {\bf F}_{{\rm BB}}^{\rm (2)} - {\bf V}_{\rm mu} \|^2_{\rm F}$, where ${\bf V}_{\rm mu}$ includes the eigenvectors of $\widehat{\bf H}_{\rm mu}^{\rm H}{\bf W}_{\rm mu}{\bf W}_{\rm mu}^{\rm H}\widehat{\bf H}_{\rm mu}$ that correspond to {the} $U \times N_{\rm s}$ largest eigenvalues, $\widehat{\bf H}_{\rm mu}$ is the estimated multi-user channel $\widehat{\bf H}_{\rm mu} = [\widehat{\bf H}_1^{\rm T},\ldots, \widehat{\bf H}_U^{\rm T}]^{\rm T}$, and ${\bf W}_{\rm mu} = {\rm diag}({\bf W}_{{\rm RF},1} {\bf W}_{{\rm BB},1}^{\rm (2)}, \ldots, {\bf W}_{{\rm RF},U} {\bf W}_{{\rm BB},U}^{\rm (2)})$.

The effective channel of receiver $u$ is ${\bf H}_{{\rm eff},u} = \widehat{\bf H}_{{\rm eff},u} + {\boldsymbol \Delta}_{{\rm eff},u}$, where $\widehat{\bf H}_{{\rm eff},u} = {\bf W}_{{\rm BB},u}^{\rm (2)H}{\bf W}_{{\rm RF},u}^{\rm H}\widehat{\bf H}_u\times$
$ {\bf F}_{{\rm RF}} {\bf F}_{{\rm BB}}^{\rm (2)}$ and ${\boldsymbol \Delta}_{{\rm eff},u} = {\bf W}_{{\rm BB},u}^{\rm (2)H}{\bf W}_{{\rm RF},u}^{\rm H}\boldsymbol \Delta_u{\bf F}_{{\rm RF}} {\bf F}_{{\rm BB}}^{\rm (2)}$. Similar to \eqref{effective_norm}, we have\vspace{-5 pt}
\begin{multline}\label{delta_eq}
\|\boldsymbol\Delta_{{\rm eff},u}\|_{\rm F}^2 = \boldsymbol\delta_u^{\rm H} {\bf A}_{{\rm RF},u} \boldsymbol\delta_u =
\boldsymbol\delta_u^{\rm H} {\bf U}_{{\rm RF},u} {\boldsymbol \Lambda}_{{\rm RF},u} {\bf U}_{{\rm RF},u}^{\rm H} \boldsymbol\delta_u = \tilde{\boldsymbol\delta}_u^{\rm H} {\boldsymbol \Lambda}_{{\rm RF},u}  \tilde{\boldsymbol\delta}_u,
\end{multline}
where $\boldsymbol\delta_u = {\rm vec}(\boldsymbol \Delta_u)$, ${\bf A}_{{\rm RF},u} = {\bf A}_{\rm F} \otimes {\bf A}_{{\rm W},u}$, and ${\bf A}_{{\rm W},u} = {\bf W}_{{\rm RF},u}{\bf W}_{{\rm BB},u}^{(2)}{\bf W}_{{\rm BB},u}^{\rm (2) H}{\bf W}_{{\rm RF},u}^{\rm H}$. Therefore, $\|\boldsymbol\Delta_{{\rm eff},u}\|_{\rm F}^2 = \sum_{n=1}^{UN_{\rm s}^2}\lambda^u_{{\rm RF},n}|\tilde{\delta}_n^u|^2 \approx \sum_{n=1}^{UN_{\rm s}^2}|\tilde{\delta}_n^u|^2$, where $\tilde{\delta}_n^u$ is the entry $n$ of $\boldsymbol\delta_u$ and $\lambda^u_{{\rm RF},n}$ is the $n^{\rm th}$ eigenvalue of ${\bf A}_{{\rm RF},u}$. As a result, $\|\boldsymbol\Delta_{{\rm eff},u}\|_{\rm F}^2$ has Erlang distribution with shape $U \times N^2_{\rm s}$, rate $\sigma_e^{-2}$, and CDF $\phi_3(\cdot)$. Hence, ${\rm Pr}\{\|\boldsymbol\Delta_{{\rm eff},u} \|_{\rm F}\le \varepsilon_{{\rm eff}}\} =  P_{\rm in}$, which implies $\varepsilon_{\rm eff}^2 = \phi_3^{-1}(P_{\rm in})$.
\vspace{-10 pt}
\subsection{Multi-User Iterative HB Scheme}
We extend our iterative scheme in Section \ref{iterative_section} to {multi-user (MU)-MIMO} systems. From \eqref{s_mu}, we have
\begin{multline}\label{s_eff}
\hat{\bf{s}}_u = {\bf{W}}_{{\rm BB},u}^{\rm (1)H}{\bf H}_{{\rm eff}, u}{\bf F}_{{\rm BB},u}^{(1)}{\bf s}_u +
 \sum \limits_{u' \neq u} {\bf{W}}_{{\rm BB},u}^{\rm H(1)}{\bf H}_{{\rm eff}, u}{\bf F}_{{\rm BB},u'}^{(1)}{\bf s}_{u'} + {\bf{W}}_{{\rm BB},u}^{\rm (1)H}\widetilde{\bf n}_u,
\end{multline}
where $\widetilde{\bf n}_u = {\bf W}_{{\rm BB},u}^{\rm (2) H}{\bf W}_{{\rm RF},u}^{\rm H}{\bf n}_u$. After some manipulations, we get
\begin{equation}\label{e_mu}
\begin{array}{ll}
{\bf E}_u =& {\mathbb E} \left\{({\bf s}_u - \hat{\bf s}_u)({\bf s}_u - \hat{\bf s}_u)^{\rm H}  \right\} = 
&{\bf W}_{{\rm BB},u}^{\rm (1)H}{\bf H}_{{\rm eff}, u}{\bf F}_{\rm BB}^{(1)}{\bf F}_{\rm BB}^{\rm (1)H}{\bf H}_{{\rm eff}, u}^{\rm H} {\bf W}_{{\rm BB},u}^{\rm (1)} -
& 2 {\rm Re}\left\{ {\bf W}_{{\rm BB},u}^{\rm (1)H}{\bf H}_{{\rm eff}, u}{\bf F}_{{\rm BB},u}^{(1)} \right\} +
&{\bf{W}}_{{\rm BB},u}^{\rm (1)H}{\bf R}_{{\rm n},u}{\bf{W}}_{{\rm BB},u}^{\rm (1)} + {\bf I}_{N_{\rm s}},
\end{array}
\end{equation}
where ${\bf R}_{{\rm n},u} = \sigma_{\rm n}^2{\bf W}_{{\rm BB},u}^{\rm (2) H}{\bf W}_{{\rm RF},u}^{\rm H} {\bf W}_{{\rm BB},u}^{\rm (2)}{\bf W}_{{\rm RF},u}$.

In what follows, we analyze the feasibility of our MU-MIMO HB. Similar to the  single-user MIMO HB, we introduce a set of non-negative variables, and solve the sample problem \eqref{sampled_problem_mu},
\begin{figure*}
\begin{equation}\label{sampled_problem_mu}
\begin{array}{ccc}
& \mathop{\min}\limits_{{\bf F}_{\rm BB}^{\rm (1)},\{{\bf W}_{{\rm BB},u}^{\rm (1)}\}_{u=1}^U,{\boldsymbol \alpha}} &  \gamma{\rm Tr}\left(  {\bf{F}}_{\rm{BB}}^{\rm (1)H}{\bf A}_{\rm P}{\bf{F}}_{\rm BB}^{(1)} \right) + (1-\gamma)\sum\limits_{u=1}^U\sum\limits_{k=1}^{N_{\rm s}}\alpha_{u,k}
& \text{subject to}&\left\{
\begin{array}{l}
{\bf E}_{u,k}({\bf F}_{\rm BB}^{\rm (1)},{\bf W}_{{\rm BB},u}^{\rm (1)};{\boldsymbol \Delta}_{u,k}^{\rm wc})\le \rho_{u,k} + \alpha_{u,k}, \quad \forall u, k \text{ and } \forall {\boldsymbol \Delta}_{u,k}^{\rm wc}\in \mathcal{D}_{u,k}^q
\alpha_{u,k}\ge 0, \quad \forall u,k,
\end{array}
\right.
\end{array}
\end{equation}
\hrulefill
\end{figure*}
where ${\bf E}_{u,k}(\cdot)$ is {the} MSE of data stream $k$ estimated by receiver $u$. Solving \eqref{sampled_problem_mu} is similar to solving \eqref{sampled_problem} via Algorithm \ref{sampled_algorithm}. However, we need to find quadratic expressions for ${\bf E}_{u,k}(\cdot)$ in terms of ${\bf F}_{\rm BB}^{\rm (1)}$ (similar to \eqref{qcqp_problem}) and ${\bf W}_{{\rm BB},u}^{\rm (1)}$ (similar to \eqref{bbc_problem}). From \eqref{e_mu}, we get
\begin{equation}\label{bbp_mu}
{\bf E}_{u,k} = {\bf f}_{\rm BB}^{\rm (1)H}{\bf A}_{u,k}^{\rm W} {\bf f}_{\rm BB}^{(1)}-2{\rm Re}\left\{ {\bf f}_{u,k}^{\rm (1)H}{\bf b}_{u,k}^{\rm W} \right\}+{\bf{w}}_{u,k}^{\rm (1)H}{\bf R}_{{\rm n},u}{\bf{w}}_{u,k}^{(1)}+1,
\end{equation}
where ${\bf f}_{\rm BB}^{(1)} = {\rm vec}({\bf F}_{\rm BB}^{(1)})$, ${\bf f}_{u,k}^{\rm (1)}$ is the $((u-1)N_{\rm s}+k)^{\rm th}$ column of ${\bf F}_{\rm BB}^{(1)}$, ${\bf w}_{u,k}^{(1)}$ is column $k$ of ${\bf W}_{{\rm BB},u}^{\rm (1)}$, ${\bf A}_{u,k}^{\rm W} = {\bf I}_{UN_{\rm s}} \otimes {\bf H}_{u,k}^{\rm wcH}{\bf{w}}_{u,k}^{(1)}{\bf{w}}_{u,k}^{\rm (1)H}{\bf H}_{u,k}^{\rm wc}$, ${\bf b}_{u,k}^{\rm W} = {\bf H}_{u,k}^{\rm wcH}{\bf{w}}_{u,k}^{(1)}$, and ${\bf H}_{u,k}^{\rm wc} = \widehat{\bf H}_{{\rm eff}, u}+ {\boldsymbol \Delta}_{u,k}^{\rm wc}$. The quadratic expression for ${\bf E}_{u,k}(\cdot)$ in terms of ${\bf W}_{{\rm BB},u}^{\rm (1)}$ is\vspace{-5 pt}
\begin{equation}\label{bbc_mu}
{\bf E}_{u,k} = {\bf w}_{u,k}^{\rm (1)H}{\bf A}_{u}^{\rm F} {\bf w}_{u,k}^{(1)}-2{\rm Re}\left\{ {\bf w}_{u,k}^{\rm (1)H}{\bf b}_{u,k}^{\rm F} \right\}+1,
\end{equation}
where ${\bf A}_{u}^{\rm F} = {\bf H}_{u,k}^{\rm wc}{\bf F}_{\rm BB}^{(1)}{\bf F}_{\rm BB}^{\rm (1)H} {\bf H}_{u,k}^{\rm wcH}+{\bf R}_{{\rm n},u}$ and ${\bf b}_{u,k}^{\rm F} = {\bf H}_{u,k}^{\rm wc}{\bf f}_{u,k}^{\rm (1)}$.

{The worst-case analysis} requires finding ${\boldsymbol \Delta}_{u,k}^{\rm wc}$. Similar to \eqref{mse_delta}, we write
\begin{equation}\label{mse_delta_mu}
{\bf E}_{u,k} = {\boldsymbol \delta}_{{\rm eff},u}^{\rm H} {\bf A}^{\delta}_{u,k} {\boldsymbol \delta}_{{\rm eff},u} +  2{\rm Re}\{ {\boldsymbol \delta}_{{\rm eff},u}^{\rm H}{\bf b}^{\delta}_{u,k}\} + \widehat{\bf E}_{u,k},
\end{equation}
\begin{figure*}
\begin{equation}\label{mse_bb_mu}
\begin{array}{ll}
{\bf E}_{u}= &\widehat{\bf E}_{u} +
2\underbrace{{\rm Re}\left\{{\bf W}_{{\rm BB},u}^{\rm (1)H}{\boldsymbol \Delta}_{{\rm eff},u}\left[\bar{\bf F}_u\widehat{\bf H}_{{\rm eff}, u}^{\rm H}{\bf W}_{{\rm BB},u}^{\rm (1)} + {\bf F}_{{\rm BB},u}^{\rm (1)}\left({\bf F}_{{\rm BB},u}^{\rm (1)H}\widehat{\bf H}_{{\rm eff},u}^{\rm H}{\bf W}_{{\rm BB}, u}^{\rm (1)}-{\bf I}_{N_{\rm s}}\right)\right]\right\}}_{{\bf X}_u}+
&\underbrace{{\bf W}_{{\rm BB}, u}^{\rm (1)H}{\boldsymbol \Delta}_{{\rm eff},u}{\bf F}_{\rm BB}^{(1)}{\bf F}_{\rm BB}^{\rm (1)H}{\boldsymbol \Delta}_{{\rm eff},u}^{\rm H}{\bf W}_{{\rm BB}, u}^{\rm (1)}}_{{\bf Y}_u},
\end{array}
\end{equation}
\hrulefill
\end{figure*}
where ${\boldsymbol \delta}_{{\rm eff},u} = {\rm vec}({\boldsymbol \Delta}_{{\rm eff},u})$, ${\bf A}^{\delta}_{u,k} = {\bf F}_{\rm BB}^{(1)*}{\bf F}_{\rm BB}^{\rm (1)T} \otimes {\bf w}_{u,k}^{\rm (1)}{\bf w}_{u,k}^{\rm (1)H}$, ${\bf b}^{\delta}_{u,k} = ({\bf F}_{\rm BB}^{(1)}{\bf F}_{\rm BB}^{\rm (1)H} \widehat{\bf H}_{{\rm eff},u}^{\rm H}{\bf w}_{u,k}^{\rm (1)} - {\bf f}_{u,k}^{\rm (1)})^* \otimes {\bf w}_{u,k}^{\rm (1)}$, and $\widehat{\bf E}_{u,k}$ is obtained from \eqref{e_mu} by replacing ${\bf H}_{{\rm eff}, u}$ with $\widehat{\bf H}_{{\rm eff}, u}$. Finding the maximizer of \eqref{mse_delta_mu}, i.e., ${\boldsymbol \Delta}_{u,k}^{\rm wc}$, is similar to finding the worst-case effective channel for the single-user HB.

All {of the} steps in our iterative scheme for single-user HB in Fig. \ref{flowchart2} are applicable to multi-user HB with appropriate substitutions as described above. As such, extending our discussions on convergence and CC of our iterative scheme from single-user HB to multi-user HB is straightforward.\vspace{-3 mm}
\subsection{Low-Complexity HB for Multi-User MIMO Systems}

Similar to Section \ref{low_section}, we introduce ${\bf F}_{{\rm BB},u}^{\rm (1)}$ and ${\bf W}_{{\rm BB},u}^{\rm (1)}$, and derive the sufficient condition for feasibility of each individual data stream. We adopt block diagonalization (BD) for {the} baseband precoder, i.e., ${\bf F}_{{\rm BB},u}^{\rm (1)} = \bar{\bf V}_u^{(0)}{\bf V}_u {\bf P}_{u}^{\frac{1}{2}}$, where the columns of $\bar{\bf V}_u^{(0)}$ span the null space of $\bar{\bf H}_u = [\widehat{\bf H}_{{\rm eff}, 1},\ldots, \widehat{\bf H}_{{\rm eff}, u-1}, \widehat{\bf H}_{{\rm eff}, u+1},\ldots,\widehat{\bf H}_{{\rm eff}, U}]$, obtained by SVD of $\bar{\bf H}_u = \bar{\bf U}_u [\bar{\boldsymbol \Sigma}_u  \quad {\bf 0}][\bar{\bf V}_u^{(1)} \quad \bar{\bf V}_u^{(0)}]^{\rm H}$. The value of ${\bf V}_u$ is obtained by SVD of  ${\bf R}_{{\rm n},u}^{-\frac{1}{2}}\widehat{\bf H}_{{\rm eff}, u}\bar{\bf V}_u^{(0)} = {\bf U}_u {\boldsymbol \Sigma}_u {\bf V}_u$.

For MMSE combining, i.e., ${\bf W}_{{\rm BB},u}^{(1)} = \left( \widehat{\bf H}_{{\rm eff},u}{\bf F}_{{\rm BB},u}^{(1)}{\bf F}_{{\rm BB},u}^{\rm (1)H} \widehat{\bf H}_{{\rm eff},u}^{\rm H} + {\bf R}_{{\rm n},u}\right)^{-1} \widehat{\bf H}_{{\rm eff},u}{\bf F}_{{\rm BB},u}^{(1)}$ in the baseband combiner of receiver $u$, and from \eqref{e_mu}, we get \eqref{mse_bb_mu}, where $\bar{\bf F}_u = \sum \limits_{u' \neq u} {\bf F}_{{\rm BB},u'}^{\rm (1)}{\bf F}_{{\rm BB},u'}^{\rm (1)H}$. By BD precoding, we have $\widehat{\bf H}_{{\rm eff}, u}{\bf F}_{{\rm BB},u'}^{\rm (1)} = \bf 0$, $\forall u'\neq u$, resulting in $\bar{\bf F}_u\widehat{\bf H}_{{\rm eff}, u}^{\rm H} = \bf 0$. Hence,
\begin{equation}
{\bf X}_u = {\rm Re}\left\{{\bf W}_{{\rm BB},u}^{\rm (1)H}{\boldsymbol \Delta}_{{\rm eff},u}{\bf F}_{{\rm BB},u}^{\rm (1)}\left({\bf F}_{{\rm BB},u}^{\rm (1)H}\widehat{\bf H}_{{\rm eff},u}^{\rm H}{\bf W}_{{\rm BB}, u}^{\rm (1)}-{\bf I}_{N_{\rm s}}\right)\right\},
\end{equation}
which is similar to \eqref{mse_bb}. Therefore, the maximum value of $[{\bf X}_u]_{k,k}$ is
\begin{equation}\label{x_wc_mu}
[{\bf X}^{\rm wc}_u]_{k,k} = \frac{\sigma_{u,k}  p_{u,k}}{(1+\sigma_{u,k}^2  p_{u,k})^2} \beta_{u,k} \varepsilon_{\rm eff},
\end{equation}
where  $\beta_{u,k} =\sqrt{{\bf u}^{\rm H}_{u,k} {\bf R}_{{\rm n},u}^{-1} {\bf u}_{u,k}}$, ${\bf u}_{u,k}$ is column $k$ of ${\bf U}_u$, and $\sigma_{u,k}$ and $p_{u,k}$ are the $k^{\rm th}$ diagonal elements of ${\boldsymbol \Sigma}_u$ and ${\bf P}_u$, respectively.

BD baseband precoding gives ${\bf F}_{\rm BB}^{(1)}{\bf F}_{\rm BB}^{\rm (1)H} = \sum_{u=1}^U  \bar{\bf V}_u^{(0)}{\bf V}_u {\bf P}_{u}{\bf V}_u^{\rm H} \bar{\bf V}_u^{\rm (0)H} = {\bf V}_{\rm mu} {\bf P}_{\rm mu} {\bf V}_{\rm mu}^{\rm H}$, where ${\bf V}_{\rm mu} = [\bar{\bf V}_1^{(0)}{\bf V}_1,\ldots,\bar{\bf V}_U^{(0)}{\bf V}_U]$ and ${\bf P}_{\rm mu} = {\rm diag}({\bf P}_{1},\ldots,{\bf P}_{U})$. Hence,\vspace{-5 pt}
\begin{equation}
{\bf Y}_u = {\bf W}_{{\rm BB}, u}^{\rm (1)H}{\boldsymbol \Delta}_{{\rm eff},u}{\bf V}_{\rm mu} {\bf P}_{\rm mu} {\bf V}_{\rm mu}^{\rm H}{\boldsymbol \Delta}_{{\rm eff},u}^{\rm H}{\bf W}_{{\rm BB}, u}^{\rm (1)},
\end{equation}
which is similar to \eqref{mse_bb}. Therefore, the maximum value of $[{\bf Y}_u]_{k,k}$ is\vspace{-5 pt}
\begin{equation}\label{y_wc_mu}
[{\bf Y}_u^{\rm wc}]_{k,k} = \frac{\sigma_{u,k}^2  p_{u,k} p_{\rm max}}{(1+\sigma_{u,k}^2  p_{u,k})^2}\varepsilon_{\rm eff}^2\beta_{u,k}^2,
\end{equation}
where $p_{\rm max} = \max\limits_{u,k} p_{u,k}$. {With} BD baseband precoding and MMSE baseband combining, we have $\widehat{\bf E}_{u,k} = \frac{1}{1+\sigma_{u,k}^2 p_{u,k}}$. {The worst-case MSE} in \eqref{mse_bb_mu} is similar to {the} worst-case MSE in \eqref{wc_mse} by substituting subscript $k$ with $u,k$. As a result, {the} feasibility analysis and transmit power allocation in our low-complexity scheme in Section \ref{low_section} are also valid for MU-MIMO HB.
